class Solution {
public:
    long long numberOfSubstrings(string s, int k) {
        int n = s.size();
        vector<int> count(26, 0);
        long long ans = 0;
        int left = 0;
        for (int right = 0; right < n; ++right) {
            int idx = s[right] - 'a';
            count[idx]++;
            while (count[idx] >= k) {
                ans += (n - right);
                count[s[left] - 'a']--;
                left++;
            }
        }
        return ans;
    }
};

class Solution {
    public long numberOfSubstrings(String s, int k) {
        int n = s.length();
        int[] count = new int[26];
        long ans = 0;
        int left = 0;
        for (int right = 0; right < n; right++) {
            int idx = s.charAt(right) - 'a';
            count[idx]++;
            while (count[idx] >= k) {
                ans += (n - right);
                count[s.charAt(left) - 'a']--;
                left++;
            }
        }
        return ans;
    }
}

